// Embed optimized codex portraits in the single-file build.
const fs = require('node:fs');
const path = require('node:path');
const root = path.resolve(__dirname, '..');
const ids = 'slime bat skel brute gob jelly mush boar knight wisp bargan igna morden seren demon'.split(' ');
const portraits = Object.fromEntries(ids.map(id => {
  const file = path.join(root, 'assets', 'codex-portraits', id + '.webp');
  return [id, 'data:image/webp;base64,' + fs.readFileSync(file).toString('base64')];
}));
fs.writeFileSync(path.join(root, 'src', 'codex-portrait-data.js'),
  '/* Generated by node dev/pack-codex-portraits.cjs. */\nconst CODEX_PORTRAITS = ' + JSON.stringify(portraits, null, 2) + ';\n');
